package com.garagedesk.service; import com.garagedesk.entity.Mechanic; import com.garagedesk.exception.ResourceNotFoundException; import com.garagedesk.repo.MechanicRepository; import org.springframework.stereotype.Service; import java.util.*; @Service public class MechanicService{final MechanicRepository r;public MechanicService(MechanicRepository r){this.r=r;}public List<Mechanic> all(){return r.findAll();}public Mechanic get(Long id){return r.findById(id).orElseThrow(()->new ResourceNotFoundException("Mechanic not found: "+id));}public Mechanic save(Mechanic x){return r.save(x);}public Mechanic update(Long id,Mechanic x){Mechanic m=get(id);m.setName(x.getName());m.setSpecialization(x.getSpecialization());m.setAvailable(x.isAvailable());return r.save(m);}public void delete(Long id){r.delete(get(id));}}
